import React from 'react';
import ComicCard from '../components/ComicCard';

const comics = [
  { id: 1, title: 'The Brave Hero', genre: 'Action', image: 'https://via.placeholder.com/300x450?text=Brave+Hero', description: 'An epic adventure of a hero fighting for justice.' },
  { id: 2, title: 'Galaxy Tales', genre: 'Sci-Fi', image: 'https://via.placeholder.com/300x450?text=Galaxy+Tales', description: 'A thrilling journey through the stars, where space adventures never end.' },
  { id: 3, title: 'The Lost City', genre: 'Adventure', image: 'https://via.placeholder.com/300x450?text=Lost+City', description: 'A group of explorers uncover the mysteries of a hidden city.' },
  { id: 4, title: 'Mystery Mansion', genre: 'Mystery', image: 'https://via.placeholder.com/300x450?text=Mystery+Mansion', description: 'Unravel the secrets hidden within an old mansion.' },
  { id: 5, title: 'Dragon Slayer', genre: 'Fantasy', image: 'https://via.placeholder.com/300x450?text=Dragon+Slayer', description: 'A brave knight sets out to defeat a terrifying dragon.' },
  { id: 6, title: 'Mega Punch Man', genre: 'Comedy', image: 'https://via.placeholder.com/300x450?text=Mega+Punch+Man', description: 'A superhero who defeats villains with one punch—and lots of jokes.' },
  { id: 7, title: 'Zombie High', genre: 'Horror', image: 'https://via.placeholder.com/300x450?text=Zombie+High', description: 'Students fight zombies while trying to pass math exams.' },
  { id: 8, title: 'Cyber City', genre: 'Sci-Fi', image: 'https://via.placeholder.com/300x450?text=Cyber+City', description: 'A futuristic city controlled by AI—until the robots go rogue.' },
  { id: 9, title: 'Time Twisters', genre: 'Adventure', image: 'https://via.placeholder.com/300x4 { 50?text=Time+Twisters', description: 'Teenagers with a broken time machine explore different eras.' },
 {id: 10, title: 'Kitty Crusaders', genre: 'Fantasy', image: 'https://via.placeholder.com/300x450?text=Kitty+Crusaders', description: 'Cats with swords, armor, and magical whiskers—need we say more?' }
];

function Comics() {
  return (
    <div className="container mt-5">
      <h2 className="text-center mb-4 text-primary">📚 All Comics</h2>
      <div className="row">
        {comics.map(comic => (
          <ComicCard key={comic.id} comic={comic} />
        ))}
      </div>
    </div>
  );
}

export default Comics;
